function renderDerived(){$('derivedCount').textContent=`${state.derived.length} 个`;$('derivedList').innerHTML=state.derived.map(x=>`<div class="derived-item"><strong>${escapeHTML(x.name)}</strong><span>${x.indicator_id} · ${escapeHTML(x.operation)} · ${escapeHTML(x.frequency||'')} · ${escapeHTML(x.domain||'')}</span><button class="text-button" data-derived="${x.derived_id}">编辑公式</button></div>`).join('')||'<div class="indicator-meta">尚未构建派生指标。</div>';$('derivedList').querySelectorAll('[data-derived]').forEach(b=>b.onclick=()=>loadDerived(b.dataset.derived))}
function loadDerived(id){const item=state.derived.find(x=>x.derived_id===id);if(!item)return;const c=item.config||{};state.editingDerivedId=id;$('derivedName').value=item.name;$('derivedOperation').value=item.operation;$('derivedExpression').value=item.expression||c.expression||'';$('derivedUnit').value=item.unit||'';$('derivedDomain').value=item.domain||'派生指标';state.derivedInputs=(c.inputs||[]).map(x=>({...x,key:uid(),transform:x.transform||'level',lag_periods:Number(x.lag_periods)||0}));renderDerivedInputs();switchView('factory')}
function resetDerivedForm(){state.editingDerivedId=null;state.derivedInputs=[];$('derivedName').value='';$('derivedOperation').value='level';$('derivedExpression').value='';$('derivedUnit').value='';$('derivedDomain').value='派生指标';$('derivedIndicatorSearch').value='';renderDerivedInputs();renderDerivedSearch()}
function renderPipeline(){const p=state.pipeline||{workbooks:[],identity_queue:[]};$('pipelinePath').textContent=p.raw_dir||'—';$('pipelineStats').innerHTML=[['已入库指标',state.indicators.length.toLocaleString()],['有效观测',Number(p.observation_count||0).toLocaleString()],['原始文件快照',Number(p.source_snapshots||0).toLocaleString()],['历史修订留痕',Number(p.revision_count||0).toLocaleString()],['身份待确认',Number(p.pending_identities||0).toLocaleString()]].map(([n,v])=>`<div class="pipeline-stat"><span>${n}</span><strong>${v}</strong></div>`).join('');$('workbookStates').innerHTML=p.workbooks?.length?`<div class="pipeline-table-scroll"><table class="pipeline-table"><thead><tr><th>工作簿ID</th><th>最近模式</th><th>最近导入</th><th>最近完整审计</th><th>更新次数</th><th>增量回看</th></tr></thead><tbody>${p.workbooks.map(x=>`<tr><td>${escapeHTML(x.logical_workbook_id)}</td><td>${x.last_mode==='incremental'?'智能增量':'完整审计'}</td><td>${escapeHTML(String(x.last_imported_at||'—').slice(0,19).replace('T',' '))}</td><td>${escapeHTML(String(x.last_full_audit_at||'—').slice(0,10))}</td><td>${Number(x.update_count||0).toLocaleString()}</td><td>${Number(x.tail_days||400)}天</td></tr>`).join('')}</tbody></table></div>`:'<div class="pipeline-empty">首次更新后会显示每个Excel工作簿的增量状态。</div>';$('identityQueue').innerHTML=p.identity_queue?.length?`<div class="pipeline-table-scroll"><table class="pipeline-table"><thead><tr><th>待确认ID</th><th>来源</th><th>已有指标</th><th>新指标名称</th><th>来源ID</th><th>位置</th></tr></thead><tbody>${p.identity_queue.map(x=>`<tr><td>${escapeHTML(x.review_id)}</td><td>${escapeHTML(x.source_system)}</td><td>${escapeHTML(x.existing_name||'—')}<br><span class="indicator-meta">${escapeHTML(x.existing_indicator_id||'')}</span></td><td>${escapeHTML(x.incoming_name)}</td><td>${escapeHTML(x.external_id||'—')}</td><td>${escapeHTML(x.source_sheet)} · ${x.source_column}</td></tr>`).join('')}</tbody></table></div>`:'<div class="pipeline-empty">当前没有身份冲突。严格匹配成功的更新会自动归入原指标ID。</div>'}
function updateWorkbookSelectionSummary(){const valid=state.sourceWorkbooks.filter(x=>!x.naming_error),selected=valid.filter(x=>state.selectedWorkbooks.has(x.file)),scanAt=state.sourceScanAt?String(state.sourceScanAt).slice(11,19):'';let text=state.sourceWorkbooks.length?`本次扫描 ${scanAt||'刚刚'} · ${state.sourceWorkbooks.length} 个文件 · 已选择 ${selected.length} 个`:'尚未扫描；打开网页不会读取Excel';if(state.lastImportNotice)text+=` · 最近操作：${state.lastImportNotice}`;$('workbookSelectionSummary').textContent=text}
function renderWorkbookPicker(){const el=$('workbookPicker');if(!state.sourceWorkbooks.length){el.innerHTML='<div class="pipeline-empty">点击“选择需要更新的Excel”后，仅扫描文件名、大小和修改时间，不读取工作簿内容。</div>';updateWorkbookSelectionSummary();return}el.innerHTML=`<div class="workbook-grid">${state.sourceWorkbooks.map(x=>`<label class="workbook-option ${x.naming_error?'invalid':''}"><input type="checkbox" data-source-file="${escapeHTML(x.file)}" ${state.selectedWorkbooks.has(x.file)?'checked':''} ${x.naming_error?'disabled':''}><span><strong>${escapeHTML(x.file)}</strong><small>${escapeHTML(x.workbook_id||'命名不合规')} · ${escapeHTML(x.provider||'未知来源')} · ${x.known?'已有指标':'新文件'}${x.possibly_changed?' · 可能有更新':''}</small><small>修改 ${escapeHTML(String(x.modified_at||'—').slice(0,16).replace('T',' '))} · 上次导入 ${escapeHTML(String(x.last_imported_at||'—').slice(0,16).replace('T',' '))}</small>${x.naming_error?`<small class="workbook-error">${escapeHTML(x.naming_error)}</small>`:''}</span></label>`).join('')}</div>`;el.querySelectorAll('[data-source-file]').forEach(input=>input.onchange=()=>{input.checked?state.selectedWorkbooks.add(input.dataset.sourceFile):state.selectedWorkbooks.delete(input.dataset.sourceFile);updateWorkbookSelectionSummary()});updateWorkbookSelectionSummary()}
async function scanSourceWorkbooks({autoSelect=true}={}){const button=$('scanWorkbooks');button.disabled=true;$('workbookSelectionSummary').textContent='正在重新扫描文件目录，不读取Excel内容…';try{const r=await getJSON(`/api/source-workbooks?user_initiated=true&_=${Date.now()}`,{cache:'no-store'});state.sourceWorkbooks=r.workbooks||[];state.sourceScanAt=r.scanned_at||new Date().toISOString();if(autoSelect)state.selectedWorkbooks=new Set(state.sourceWorkbooks.filter(x=>!x.naming_error&&x.possibly_changed).map(x=>x.file));else state.selectedWorkbooks=new Set();button.textContent='重新扫描Excel目录';renderWorkbookPicker()}catch(e){showImportStatus(e.message,true)}finally{button.disabled=false}}
function selectSourceWorkbooks(mode){const valid=state.sourceWorkbooks.filter(x=>!x.naming_error);const selected=mode==='all'?valid:mode==='new'?valid.filter(x=>!x.known):mode==='changed'?valid.filter(x=>x.possibly_changed):[];state.selectedWorkbooks=new Set(selected.map(x=>x.file));renderWorkbookPicker()}
async function buildPublicPackage(){const button=$('buildPublicPackage');button.disabled=true;$('publicPackageStatus').textContent='正在从整合数据库生成客户公开包，不读取Excel…';try{const r=await getJSON('/api/build-public-package',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_initiated:true})});const m=r.manifest||{};$('publicPackageStatus').textContent=`客户公开包已生成：${Number(m.indicator_count||0).toLocaleString()} 个指标、${Number(m.chart_count||0).toLocaleString()} 张图。目录：${r.package_dir}`}catch(e){$('publicPackageStatus').textContent=e.message;$('publicPackageStatus').style.color='#b42318'}finally{button.disabled=false}}
async function reloadAll(){const [system,indicators,charts,domains,derived,pipeline]=await Promise.all([getJSON('/api/system'),getJSON('/api/indicators'),getJSON('/api/charts'),getJSON('/api/domains'),getJSON('/api/derived'),getJSON('/api/pipeline')]);state.indicators=indicators;state.charts=charts;state.derived=derived;state.pipeline=pipeline;hydrateLocalFigures();$('systemStats').textContent=`${system.indicator_count} 个指标 · ${Number(system.observation_count).toLocaleString()} 个有效观测 · ${STATIC_MODE?'客户浏览模式':'正式模式'} · 公开包生成 ${system.latest_run?.finished_at?.slice(0,16).replace('T',' ')||'—'}`;populateFilters(domains);renderDerivedSearch();renderDerivedInputs();renderDerived();renderPipeline();renderLibrary();renderGallery();renderShowcase()}
function switchView(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===`${view}View`));document.querySelectorAll('.nav-button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));if(view==='gallery')renderGallery();if(view==='factory')renderDerived();if(view==='pipeline')renderPipeline();if(view==='showcase')renderShowcase()}
function filteredIndicators(){const q=$('search').value.trim().toLowerCase(),d=$('domainFilter').value,f=$('frequencyFilter').value;return state.indicators.filter(x=>{const h=[x.name,x.indicator_id,x.external_id,x.publisher,x.source_system].join(' ').toLowerCase();return(!q||h.includes(q))&&(!d||x.domain===d)&&(!f||x.frequency===f)})}
function renderLibrary(){const all=filteredIndicators(),rows=all.slice(0,state.indicatorLimit);$('resultCount').textContent=`显示 ${rows.length} / ${all.length}`;$('indicatorList').innerHTML=rows.map(x=>`<label class="indicator-item"><input type="checkbox" data-id="${x.indicator_id}" ${state.series.some(s=>s.indicator.indicator_id===x.indicator_id)?'checked':''}><span><span class="indicator-name">${escapeHTML(x.name)}</span><span class="indicator-meta">${x.indicator_id} · ${freqLabel[x.frequency]||x.frequency} · ${escapeHTML(x.unit||'无单位')}<br>${x.first_date||'—'} → ${x.latest_date||'—'}</span></span></label>`).join('');$('indicatorList').querySelectorAll('input').forEach(el=>el.onchange=()=>toggleIndicator(el.dataset.id,el.checked));$('indicatorMore').hidden=rows.length>=all.length}
function nextSeriesAxis(){const used=activeAxisSet();if(state.series.length<4)return AXIS_ORDER.find(side=>!used.has(side))||'right';return state.series.length===0?'left':'right'}
function newSeries(indicator,base={}){const axis=base.axis||nextSeriesAxis();return{series_key:uid(),indicator,axis,chart_type:base.chart_type||'line',color:base.color||nextSeriesColor(axis),line_dash:base.line_dash||'solid',line_width:Number(base.line_width)||2.5,ma_days:Math.max(1,Number(base.ma_days)||1),shift_days:Number(base.shift_days)||0,start_date:base.start_date||indicator.first_date||DEFAULT_TIMESERIES_START,end_date:base.end_date||indicator.latest_date,end_mode:base.end_mode||'latest',label:base.label||''}}
function toggleIndicator(id,checked){const indicator=state.indicators.find(x=>x.indicator_id===id);if(checked&&!state.series.some(s=>s.indicator.indicator_id===id)){if(state.series.length>=12)return showMessage('一次最多12条序列。',true);state.series.push(newSeries(indicator))}else if(!checked)state.series=state.series.filter(s=>s.indicator.indicator_id!==id);state.chartId=null;renderSelected();syncDefaultChartTitle();updateDateDefaults();renderLibrary();refreshChart()}
function renderSelected(){
  $('selectedSeries').innerHTML=state.series.map(s=>`<div class="series-row" data-key="${s.series_key}" style="--series-axis-color:${escapeHTML(axisColor(s.axis))}">
    <div class="series-name">${escapeHTML(s.label||s.indicator.name)}<small>${s.indicator.indicator_id} · ${escapeHTML(s.indicator.publisher||s.indicator.source_system)}</small><span class="series-axis-badge">${AXIS_POSITION_LABEL[s.axis]||'左一'}</span></div>
    <select class="axis-select" aria-label="所属坐标轴"><option value="left" ${s.axis==='left'?'selected':''}>左轴1（内侧）</option><option value="left2" ${s.axis==='left2'?'selected':''}>左轴2（外侧）</option><option value="right" ${s.axis==='right'?'selected':''}>右轴1（内侧）</option><option value="right2" ${s.axis==='right2'?'selected':''}>右轴2（外侧）</option></select>
    <select class="type-select" aria-label="图形"><option value="line" ${s.chart_type==='line'?'selected':''}>折线</option><option value="bar" ${s.chart_type==='bar'?'selected':''}>柱形</option></select>
    <label class="mini-field">颜色<input class="series-color" type="color" value="${escapeHTML(s.color||AXIS_DEFAULT_COLOR[s.axis]||'#0000ff')}"></label>
    <label class="mini-field">MA<input class="ma-input" type="number" min="1" value="${s.ma_days}" title="每根线独立设置移动平均天数；1=原值"></label>
    <label class="mini-field">线型<select class="dash-select"><option value="solid" ${s.line_dash==='solid'?'selected':''}>实线</option><option value="dash" ${s.line_dash==='dash'?'selected':''}>虚线</option><option value="dot" ${s.line_dash==='dot'?'selected':''}>点线</option><option value="dashdot" ${s.line_dash==='dashdot'?'selected':''}>点划线</option></select></label>
    <label class="mini-field">粗细<input class="width-input" type="number" min="0.5" max="10" step="0.5" value="${s.line_width||2.5}"></label>
    <button class="series-copy" aria-label="复制序列" title="复制序列">＋</button><button class="series-remove" aria-label="移除序列" title="移除序列">×</button>
    <details class="series-advanced"><summary>日期与位移参数</summary><div class="series-advanced-grid">
      <label class="mini-field">领先/滞后天数<input class="shift-input" type="number" step="1" value="${s.shift_days||0}" title="正数=领先，负数=滞后"></label>
      <label class="mini-field">序列开始<input class="series-start" type="date" value="${s.start_date||''}"></label>
      <label class="mini-field">结束方式<select class="series-end-mode"><option value="latest" ${s.end_mode==='latest'?'selected':''}>最新</option><option value="fixed" ${s.end_mode==='fixed'?'selected':''}>固定</option></select></label>
      <label class="mini-field">序列结束<input class="series-end" type="date" value="${s.end_date||''}"></label>
    </div></details>
  </div>`).join('')||'<div class="indicator-meta">尚未选择指标。</div>';
  $('selectedSeries').querySelectorAll('.series-row').forEach(row=>{const s=state.series.find(x=>x.series_key===row.dataset.key);
    row.querySelector('.axis-select').onchange=e=>{const old=s.axis;s.axis=e.target.value;if(!s.color||s.color===AXIS_DEFAULT_COLOR[old])s.color=AXIS_DEFAULT_COLOR[s.axis];const validation=independentAxisValidation();if(validation.independent&&!validation.ok)showMessage(`${validation.message} 这是过渡状态，完成轴分配后即可保存。`,true);renderSelected();syncDefaultChartTitle();refreshChart()};
    row.querySelector('.type-select').onchange=e=>{s.chart_type=e.target.value;refreshChart()};
    row.querySelector('.series-color').oninput=e=>{s.color=e.target.value;row.style.setProperty('--series-axis-color',axisColor(s.axis));syncAxisUI();refreshChart()};
    row.querySelector('.dash-select').onchange=e=>{s.line_dash=e.target.value;refreshChart()};
    row.querySelector('.width-input').onchange=e=>{s.line_width=Math.min(10,Math.max(.5,Number(e.target.value)||2.5));e.target.value=s.line_width;refreshChart()};
    row.querySelector('.ma-input').oninput=e=>{if(e.target.value==='')return;s.ma_days=Math.max(1,Number(e.target.value)||1);refreshChart()};
    row.querySelector('.ma-input').onchange=e=>{s.ma_days=Math.max(1,Number(e.target.value)||1);e.target.value=s.ma_days;refreshChart();showMessage(`已应用 ${s.label||s.indicator.name} 的 MA${s.ma_days}。`)};
    row.querySelector('.shift-input').onchange=e=>{s.shift_days=Math.trunc(Number(e.target.value)||0);e.target.value=s.shift_days;refreshChart()};
    row.querySelector('.series-start').onchange=e=>{s.start_date=e.target.value;refreshChart()};
    row.querySelector('.series-end-mode').onchange=e=>{s.end_mode=e.target.value;refreshChart()};
    row.querySelector('.series-end').onchange=e=>{s.end_mode='fixed';s.end_date=e.target.value;row.querySelector('.series-end-mode').value='fixed';refreshChart()};
    row.querySelector('.series-copy').onclick=()=>{if(isIndependentMultiAxis())return showMessage('三、四轴模式每条线必须独占一根轴，不能在同一轴复制序列。',true);if(state.series.length>=12)return showMessage('一次最多12条序列。',true);state.series.push(newSeries(s.indicator,{...s,axis:s.axis}));renderSelected();syncDefaultChartTitle();refreshChart()};
    row.querySelector('.series-remove').onclick=()=>{state.series=state.series.filter(x=>x.series_key!==s.series_key);renderSelected();syncDefaultChartTitle();renderLibrary();refreshChart()}
  });syncAxisUI()
}
function updateDateDefaults(){if(!state.series.length)return;const latest=state.series.map(x=>x.indicator.latest_date).filter(Boolean).sort().at(-1);if(!$('endDate').value)$('endDate').value=latest;if(!$('startDate').value)$('startDate').value=DEFAULT_TIMESERIES_START;$('endMode').value=$('endMode').value||'latest'}
function resolvedEndDate(){const a=state.series.map(x=>x.indicator).filter(x=>x.latest_date);if(!a.length)return $('endDate').value;if($('endMode').value==='latest')return a.map(x=>x.latest_date).sort().at(-1);if($('endMode').value==='common')return a.map(x=>x.latest_date).sort()[0];return $('endDate').value}
function moving(points,n){if(n<=1)return points;const w=[];return points.map(p=>{w.push(Number(p.value));if(w.length>n)w.shift();const v=w.reduce((a,b)=>a+b,0)/w.length;return{...p,value:v,value_display:fmt(v)}})}
function shiftedDate(date,days){const d=new Date(`${date}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+Number(days||0));return d.toISOString().slice(0,10)}
function shiftLabel(days){const n=Number(days||0);return n>0?` · 领先${n}天`:n<0?` · 滞后${Math.abs(n)}天`:''}
function effectiveTimeRange(start,end,series=state.series,mode=$('endMode').value){if(!start||!end||mode==='fixed')return{start,end};const shifts=series.map(s=>Number(s.shift_days)||0),minShift=Math.min(0,...shifts),maxShift=Math.max(0,...shifts);return{start:shiftedDate(start,minShift),end:shiftedDate(end,maxShift)}}
function pointsInViewport(points,start,end){return points.filter(p=>(!start||p.date>=start)&&(!end||p.date<=end))}
function storedAxis(settings={},right=false){const a={fixedrange:false,autorange:settings.reverse?'reversed':true,zeroline:false,separatethousands:true,exponentformat:'none',showexponent:'none',automargin:true,tickformat:',.8~f'};if(settings.min!=null&&settings.max!=null){a.range=settings.reverse?[settings.max,settings.min]:[settings.min,settings.max];a.autorange=false}if(right){a.overlaying='y';a.side='right'}return a}
