orEach(b=>b.onclick=()=>{if(!state.series.length)return;const d=new Date(`${resolvedEndDate()}T00:00:00`);if(b.dataset.years==='all')$('startDate').value=state.series.map(x=>x.indicator.first_date).filter(Boolean).sort()[0];else{d.setFullYear(d.getFullYear()-Number(b.dataset.years));$('startDate').value=d.toISOString().slice(0,10)}refreshChart()});
