let toastTimer=null;
function showMessage(t,error=false){const message=$('message'),toast=$('toast');if(message){message.textContent=t;message.style.color=error?'#b42318':'#4d5a69'}if(toast){toast.textContent=t;toast.classList.toggle('error',error);toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3600)}}function escapeHTML(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
const PRESET_DOMAINS=['宏观','铜','铝','锡','碳酸锂','汇率','利率','其他'];
const AXIS_POSITION_LABEL={left:'左一',right:'右一',left2:'左二',right2:'右二'};
function orderedDomains(values=[]){const all=[...new Set([...PRESET_DOMAINS,...values].filter(Boolean).filter(x=>x!=='全部板块'&&x!=='未分类'))];return[...PRESET_DOMAINS,...all.filter(x=>!PRESET_DOMAINS.includes(x)).sort((a,b)=>a.localeCompare(b,'zh-CN'))]}

const basePopulateFilters=populateFilters;
populateFilters=function(domains){const ordered=orderedDomains(domains);state.domains=ordered;basePopulateFilters(ordered);$('domainOptions').innerHTML=ordered.map(v=>`<option value="${escapeHTML(v)}"></option>`).join('');const select=$('chartDomain'),current=select.value||'其他';select.innerHTML=ordered.map(v=>`<option value="${escapeHTML(v)}">${escapeHTML(v)}</option>`).join('');if(current&&!ordered.includes(current))select.add(new Option(current,current));select.value=current&&[...select.options].some(o=>o.value===current)?current:'其他'};

function chartNoteBox(chart){
  if(document.body.classList.contains('public-readonly'))return`<section class="chart-note-box public-chart-note" data-note-chart="${chart.chart_id}"><div class="chart-note-readonly">${escapeHTML(chart.note_text||'尚未填写说明')}</div></section>`;
  return`<section class="chart-note-box" data-note-chart="${chart.chart_id}"><textarea maxlength="4000" aria-label="${escapeHTML(chart.title)}图片说明" placeholder="输入图片简易说明">${escapeHTML(chart.note_text||'')}</textarea><footer><span>${chart.note_version?`说明 V${chart.note_version}`:'尚未填写说明'}</span><button class="secondary save-chart-note" type="button">保存说明</button></footer></section>`
}
async function saveNote(chartId,noteText,statusElement){const chart=state.charts.find(x=>x.chart_id===chartId);if(STATIC_MODE){const saved=JSON.parse(localStorage.getItem('yd-chart-notes')||'{}');saved[chartId]={note_text:noteText,version:(saved[chartId]?.version||0)+1};localStorage.setItem('yd-chart-notes',JSON.stringify(saved));if(chart){chart.note_text=noteText;chart.note_version=saved[chartId].version}if(statusElement)statusElement.textContent=`说明 V${saved[chartId].version}`;return saved[chartId]}const result=await getJSON(`/api/charts/${encodeURIComponent(chartId)}/note`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({note_text:noteText})});if(chart){chart.note_text=result.note_text;chart.note_version=result.version}if(statusElement)statusElement.textContent=`说明 V${result.version} 已保存`;return result}
function attachNoteBoxes(root){root.querySelectorAll('[data-note-chart]').forEach(box=>{const chartId=box.dataset.noteChart,textarea=box.querySelector('textarea'),status=box.querySelector('footer span'),button=box.querySelector('.save-chart-note');['click','dblclick'].forEach(type=>box.addEventListener(type,e=>e.stopPropagation()));if(!textarea||!button)return;button.onclick=async()=>{try{button.disabled=true;await saveNote(chartId,textarea.value,status)}catch(error){status.textContent=error.message}finally{button.disabled=false}}})}
function insertNoteBox(card,chart){if(card.querySelector('[data-note-chart]'))return;const visual=card.querySelector('iframe,img')||card.firstElementChild;if(visual)visual.insertAdjacentHTML('afterend',chartNoteBox(chart))}

