function seriesMagnitude(series){const points=state.seriesPayload?.series?.[series.indicator.indicator_id]||[],values=points.map(p=>Math.abs(Number(p.value))).filter(v=>Number.isFinite(v)&&v>0).sort((a,b)=>a-b);if(!values.length)return null;return values[Math.min(values.length-1,Math.floor(values.length*.9))]}
function renderAxisSuggestion(){const el=$('axisSuggestion');if(!el||isSeasonalMode($('chartMode').value)||state.series.length<2){if(el)el.hidden=true;return}const rows=state.series.map(s=>({series:s,magnitude:seriesMagnitude(s)})).filter(x=>x.magnitude);if(rows.length<2){el.hidden=true;return}rows.sort((a,b)=>a.magnitude-b.magnitude);const ratio=rows.at(-1).magnitude/rows[0].magnitude;if(ratio<20){el.hidden=true;return}const separated=new Set(state.series.map(s=>s.axis||'left')).size>1;el.hidden=false;el.textContent=`数量级提示：${rows.at(-1).series.label||rows.at(-1).series.indicator.name} 与 ${rows[0].series.label||rows[0].series.indicator.name} 的典型数量级约相差 ${fmt(ratio)} 倍。${separated?'当前已分配到多个坐标轴。':'建议改用不同坐标轴；具体选择左一、右一、左二或右二由你决定。'}`}
function decorateMultiAxisLegend(){const active=new Set(state.series.map(s=>s.axis||'left'));if(active.size<=2||!$('chart')?.data)return;const names=$('chart').data.map((trace,index)=>{const s=state.series[index];if(!s)return trace.name;const raw=String(trace.name||'').replace(/\s+\((左一|右一|左二|右二)\)$/,'');return`${raw} (${AXIS_POSITION_LABEL[s.axis||'left']})`});Plotly.restyle($('chart'),{name:names}).catch(()=>{})}
const baseRefreshChart=refreshChart;
refreshChart=async function(){await baseRefreshChart();renderAxisSuggestion();decorateMultiAxisLegend()};

function duplicateQueueHTML(groups){if(!groups?.length)return'<div class="pipeline-empty">当前没有检测到重复指标位置。</div>';return groups.map(group=>`<section class="duplicate-group"><div class="duplicate-group-heading"><strong>${escapeHTML(group.match_type)}：${escapeHTML(group.match_value)}</strong><span>${group.items.length} 个来源位置</span></div><div class="pipeline-table-scroll"><table class="pipeline-table"><thead><tr><th>指标名称</th><th>指标ID</th><th>来源ID</th><th>Excel</th><th>Sheet</th><th>指标列</th><th>日期列</th></tr></thead><tbody>${group.items.map(item=>`<tr><td>${escapeHTML(item.indicator_name)}</td><td>${escapeHTML(item.indicator_id)}</td><td>${escapeHTML(item.external_id||'—')}</td><td>${escapeHTML(item.excel_file)}</td><td>${escapeHTML(item.source_sheet)}</td><td>${Number(item.source_column)+1}</td><td>${item.source_date_column==null?'—':Number(item.source_date_column)+1}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}
const baseRenderPipeline=renderPipeline;
renderPipeline=function(){baseRenderPipeline();const labels={existing_only:'更新已有指标',discover_new:'更新并发现新指标',full_audit:'完整历史审计',incremental:'智能增量'};document.querySelectorAll('#workbookStates tbody tr').forEach((row,i)=>{const item=state.pipeline?.workbooks?.[i];if(item&&row.children[1])row.children[1].textContent=labels[item.last_mode]||item.last_mode||'—'});$('duplicateIndicatorQueue').innerHTML=duplicateQueueHTML(state.pipeline?.duplicate_groups);const stats=$('pipelineStats');if(stats&&!stats.querySelector('[data-duplicate-stat]'))stats.insertAdjacentHTML('beforeend',`<div class="pipeline-stat" data-duplicate-stat><span>重复清理建议</span><strong>${Number(state.pipeline?.duplicate_group_count||0).toLocaleString()}</strong></div>`)};

async function exportChartWithNote(frame,filename,labelLast=false,notePlacement='image'){const graph=frameGraph(frame),lib=frame?.contentWindow?.Plotly;if(!graph||!lib)return false;const original=Array.isArray(graph.layout?.annotations)?graph.layout.annotations:[];try{if(labelLast)await lib.relayout(graph,{annotations:[...original,...lastValueAnnotations(graph)]});const chartUrl=await lib.toImage(graph,{format:'png',width:1550,height:700,scale:2}),download=(href)=>{const link=document.createElement('a');link.href=href;link.download=`${filename}.png`;document.body.appendChild(link);link.click();link.remove()};if(notePlacement==='image'){download(chartUrl);return true}const image=new Image(),chart=state.charts.find(x=>x.chart_id===filename),note=chart?.note_text||'';await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=chartUrl});const canvas=document.createElement('canvas'),right=notePlacement==='note_right',noteExtent=Math.round((right?image.naturalWidth:image.naturalHeight)*(right?0.34:0.5));canvas.width=image.naturalWidth+(right?noteExtent:0);canvas.height=image.naturalHeight+(right?0:noteExtent);const ctx=canvas.getContext('2d'),pad=40,lineHeight=44,noteX=right?image.naturalWidth:0,noteY=right?0:image.naturalHeight,noteWidth=right?noteExtent:image.naturalWidth,noteHeight=right?image.naturalHeight:noteExtent;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);ctx.strokeStyle='#d9e0e7';ctx.lineWidth=2;ctx.beginPath();if(right){ctx.moveTo(noteX+1,0);ctx.lineTo(noteX+1,canvas.height)}else{ctx.moveTo(0,noteY+1);ctx.lineTo(canvas.width,noteY+1)}ctx.stroke();ctx.fillStyle='#17212b';ctx.font='700 28px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif';ctx.fillText('图片说明',noteX+pad,noteY+pad+26);ctx.font='26px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif';const maxWidth=noteWidth-pad*2,paragraphs=(note||'').split(/\n/),lines=[];for(const paragraph of paragraphs){let line='';for(const char of paragraph){const next=line+char;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=char}else line=next}lines.push(line)}const maxLines=Math.max(1,Math.floor((noteHeight-pad*2-42)/lineHeight));lines.slice(0,maxLines).forEach((line,index)=>ctx.fillText(line,noteX+pad,noteY+pad+74+lineHeight*index));download(canvas.toDataURL('image/png'));return true}catch(error){console.error('PNG export failed',error);return false}finally{if(labelLast)await lib.relayout(graph,{annotations:original})}}
exportFrame=exportChartWithNote;

function triggerPNGDownload(dataUrl,filename){
  const link=document.createElement('a');
  link.href=dataUrl;
  link.download=`${String(filename||'chart').replace(/[\\/:*?"<>|]+/g,'-')}.png`;
  document.body.appendChild(link);
  link.click();
  link.remove();
}
function canvasTextLines(ctx,text,maxWidth){
  const lines=[];
  for(const paragraph of String(text||'').split(/\n/)){
    if(!paragraph){lines.push('');continue}
    let line='';
    for(const char of paragraph){
      const next=line+char;
      if(line&&ctx.measureText(next).width>maxWidth){lines.push(line);line=char}
      else line=next;
    }
    lines.push(line);
  }
  return lines;
}
async function exportPlotWithCurrentNote(graph,lib,filename,labelLast=false,notePlacement='image',noteText=''){
  if(!graph||!lib)return false;
  const original=Array.isArray(graph.layout?.annotations)?graph.layout.annotations:[];
  try{
    if(labelLast)await lib.relayout(graph,{annotations:[...original,...lastValueAnnotations(graph)]});
    const chartUrl=await lib.toImage(graph,{format:'png',width:1550,height:700,scale:2});
    if(notePlacement==='image'){triggerPNGDownload(chartUrl,filename);return true}
    const image=new Image();
    await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=chartUrl});
    const right=notePlacement==='note_right';
    const noteExtent=right?Math.round(image.naturalWidth*.34):Math.round(image.naturalHeight*.5);
    const canvas=document.createElement('canvas');
    canvas.width=image.naturalWidth+(right?noteExtent:0);
    canvas.height=image.naturalHeight+(right?0:noteExtent);
    const ctx=canvas.getContext('2d'),pad=40,lineHeight=44;
    const noteX=right?image.naturalWidth:0,noteY=right?0:image.naturalHeight;
    const noteWidth=right?noteExtent:image.naturalWidth,noteHeight=right?image.naturalHeight:noteExtent;
    ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);
    ctx.strokeStyle='#d9e0e7';ctx.lineWidth=2;ctx.beginPath();
    if(right){ctx.moveTo(noteX+1,0);ctx.lineTo(noteX+1,canvas.height)}
    else{ctx.moveTo(0,noteY+1);ctx.lineTo(canvas.width,noteY+1)}
    ctx.stroke();
    ctx.fillStyle='#17212b';
    ctx.font='700 28px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif';
    ctx.fillText('图片说明',noteX+pad,noteY+pad+26);
    ctx.font='26px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif';
    const maxWidth=noteWidth-pad*2;
    const lines=canvasTextLines(ctx,noteText,maxWidth);
    const maxLines=Math.max(1,Math.floor((noteHeight-pad*2-42)/lineHeight));
    lines.slice(0,maxLines).forEach((line,index)=>ctx.fillText(line,noteX+pad,noteY+pad+74+lineHeight*index));
    triggerPNGDownload(canvas.toDataURL('image/png'),filename);
    return true;
  }catch(error){
    console.error('PNG export failed',error);
    return false;
  }finally{
    if(labelLast)await lib.relayout(graph,{annotations:original});
  }
}
async function exportFrameWithCurrentNote(frame,filename,labelLast=false,notePlacement='image',noteText){
  const chart=state.charts.find(x=>x.chart_id===filename);
  const currentViewerNote=state.viewerChartId===filename?$('viewerNoteText')?.value:undefined;
  const resolvedNote=noteText??currentViewerNote??chart?.note_text??'';
  return exportPlotWithCurrentNote(frameGraph(frame),frame?.contentWindow?.Plotly,filename,labelLast,notePlacement,resolvedNote);
}
exportFrame=exportFrameWithCurrentNote;

const baseBindControls=bindControls;
bindControls=function(){
  baseBindControls();
  $('addDomain').onclick=async()=>{const input=$('newDomainName'),name=input.value.trim();if(!name)return showMessage('请输入自定义板块名称。',true);try{let domain=name;if(!STATIC_MODE){const result=await getJSON('/api/domains',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});domain=result.domain}state.domains=orderedDomains([...(state.domains||[]),domain]);populateFilters(state.domains);$('chartDomain').value=domain;input.value='';showMessage(`已新增板块：${domain}`)}catch(error){showMessage(error.message,true)}};
  $('exportDraft').onclick=async()=>{
    const graph=$('chart');
    if(!state.series.length||!graph?.data?.length)return showMessage('请先选择指标并生成图表。',true);
    $('exportDraft').disabled=true;
    try{
      const filename=($('chartTitle').value||'未命名图表')+'-草稿';
      const ok=await exportPlotWithCurrentNote(graph,Plotly,filename,$('draftLabelLast').checked,$('draftExportMode').value,$('chartNote').value);
      showMessage(ok?'草稿 PNG 已导出；本次导出不会自动加入图库。':'草稿导出失败，请稍后重试。',!ok);
    }finally{$('exportDraft').disabled=false}
  };
  $('viewerExport').onclick=async e=>{
    e.preventDefault();
    const c=state.charts.find(x=>x.chart_id===state.viewerChartId);
    const ok=await exportFrame($('viewerFrame'),c?.chart_id||'chart',$('viewerLabelLast').checked,$('viewerExportMode').value,$('viewerNoteText').value);
    if(ok){setViewerStatus('PNG 已导出');showMessage('PNG 已导出。')}
    else{setViewerStatus('图表仍在加载，请稍后再导出。',true);showMessage('图表仍在加载，请稍后再导出。',true)}
  };
};


const publicHydrateLocalFigures=hydrateLocalFigures;
let publicPlotlyPromise=null;
function ensurePublicPlotly(){
  if(window.Plotly)return Promise.resolve(window.Plotly);
  if(publicPlotlyPromise)return publicPlotlyPromise;
  publicPlotlyPromise=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='https://cdn.plot.ly/plotly-3.0.1.min.js';
    script.async=true;
    script.onload=()=>resolve(window.Plotly);
    script.onerror=()=>reject(new Error('图表组件加载失败，请检查网络后重试。'));
    document.head.appendChild(script);
  });
  return publicPlotlyPromise;
}
hydrateLocalFigures=function(){
  if(window.GALLERY_BOOTSTRAP?.series)publicHydrateLocalFigures();
};
async function ensurePublicChartFigure(chart){
  if(!STATIC_MODE||chart?.figure||!chart?.config?.series?.length)return;
  await ensurePublicPlotly();
  const config=chart.config||{};
  const ids=[...new Set((config.series||[]).map(item=>item.indicator_id).filter(Boolean))];
  if(!ids.length)return;
  const seasonal=config.chart_mode==='seasonal'||config.chart_mode==='seasonal_cny';
  const seasonalYears=(config.seasonal_years||[]).map(Number).filter(Number.isFinite);
  const starts=(config.series||[]).map(item=>item.start_date).filter(Boolean).sort();
  const ends=(config.series||[]).map(item=>item.end_date).filter(Boolean).sort();
  const start=seasonal
    ?(seasonalYears.length?Math.min(...seasonalYears)+'-01-01':state.indicators.find(item=>item.indicator_id===ids[0])?.first_date||'2010-01-01')
    :(config.start_date||starts[0]||'2010-01-01');
  const latest=ids.map(id=>state.indicators.find(item=>item.indicator_id===id)?.latest_date).filter(Boolean).sort().pop();
  const end=seasonal
    ?(seasonalYears.length?Math.max(...seasonalYears)+'-12-31':latest||'9999-12-31')
    :(config.end_mode==='latest'?(latest||'9999-12-31'):(config.end_date||ends.pop()||latest||'9999-12-31'));
  const payload=await getJSON(`/api/series?${new URLSearchParams({ids:ids.join(','),start,end})}`);
  const bootstrap=window.GALLERY_BOOTSTRAP;
  const oldSeries=bootstrap.series;
  const oldCharts=state.charts;
  bootstrap.series=payload.series;
  state.charts=[chart];
  try{publicHydrateLocalFigures()}finally{
    state.charts=oldCharts;
    bootstrap.series=oldSeries;
  }
}
const publicOpenViewer=openViewer;
openViewer=async function(chartId,origin){
  const chart=state.charts.find(item=>item.chart_id===chartId);
  try{await ensurePublicChartFigure(chart)}
  catch(error){showMessage(error.message,true);return}
  return publicOpenViewer(chartId,origin);
};
const publicLoadChart=loadChart;
loadChart=async function(chartId){
  await ensurePublicPlotly();
  return publicLoadChart(chartId);
};

